import asyncio
import json
import logging
from typing import Tuple, List
from openai import AsyncOpenAI
import config

logging.basicConfig(level=config.LOG_LEVEL)
logger = logging.getLogger(__name__)

async def evaluate_complexity(query: str, client: AsyncOpenAI) -> Tuple[int, List[str]]:
    system_prompt = """You are an expert evaluator. Assess the complexity of the following query on a scale of 1-10:

1 = Simple factual question (e.g., "What is the capital of France?")
2-3 = Basic information retrieval
4-5 = Moderate complexity requiring some analysis
6-7 = Complex analysis or multi-step reasoning
8-9 = Advanced problem-solving requiring domain expertise
10 = PhD-level research or extremely complex multi-domain problems

Respond with ONLY a JSON object in this format:
{
  "complexity": <number 1-10>,
  "reasoning": "<brief explanation>",
  "recommended_specializations": ["<specialization1>", "<specialization2>", ...]
}"""

    try:
        response = await client.chat.completions.create(
            model=config.MODEL,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": f"Evaluate this query: {query}"}
            ],
            temperature=config.TEMPERATURE_EVALUATION,
            timeout=config.TIMEOUT
        )

        content = response.choices[0].message.content.strip()

        try:
            result = json.loads(content)
            complexity = result.get("complexity", 5)
        except json.JSONDecodeError:
            import re
            match = re.search(r'"complexity"\s*:\s*(\d+)', content)
            if match:
                complexity = int(match.group(1))
            else:
                complexity = 5

        logger.info(f"Query complexity evaluated: {complexity}/10")

        if complexity <= config.COMPLEXITY_THRESHOLD_SINGLE:
            return 1, ["generalist"]

        num_agents = min(
            config.MAX_AGENTS,
            max(config.MIN_AGENTS, round(complexity * config.AGENT_MULTIPLIER))
        )

        roles = assign_roles(num_agents)

        logger.info(f"Spawning {num_agents} agents with roles: {roles}")

        return num_agents, roles

    except Exception as e:
        logger.error(f"Error evaluating complexity: {e}")
        return config.MIN_AGENTS, assign_roles(config.MIN_AGENTS)

def assign_roles(num_agents: int) -> List[str]:
    roles = []
    base_roles = ["reasoner", "researcher", "critic", "creator", "validator"]

    for role, percentage in config.ROLE_DISTRIBUTION.items():
        count = max(1, int(num_agents * percentage))
        roles.extend([role] * count)

    while len(roles) < num_agents:
        roles.extend(base_roles)

    return roles[:num_agents]
