    Focus on:
    - Comprehensive understanding
    - Balanced perspective
    - Clear communication
    - Practical solutions"""
}

async def run_agent(
    client: AsyncOpenAI,
    agent_id: int,
    role: str,
    query: str,
    tools: List[Dict[str, Any]],
    context: str = ""
) -> Dict[str, Any]:

    role_prompt = ROLE_PROMPTS.get(role, ROLE_PROMPTS["generalist"])

    system_prompt = f"""{role_prompt}

Task: Analyze the following query and generate 1-3 hypotheses or solutions.

For each hypothesis:
1. Clearly state your hypothesis/solution
2. Provide reasoning and evidence
3. Assign a confidence score (0.0 to 1.0)
4. List any tools you used
5. Provide a self-evaluation of strengths and weaknesses

You MUST respond with valid JSON in this exact format:
{{
  "agent_id": {agent_id},
  "role": "{role}",
  "hypotheses": [
    {{
      "text": "Your hypothesis or solution here",
      "reasoning": "Detailed reasoning and evidence",
      "confidence": 0.0-1.0,
      "tools_used": ["tool1", "tool2"]
    }}
  ],
  "self_eval": "Honest assessment of your analysis strengths and limitations"
}}

Think step-by-step. Prioritize accuracy and truth-seeking. Be thorough but concise."""

    user_content = query
    if context:
        user_content = f"Query: {query}\n\nAdditional Context:\n{context}"

    messages = [
        {"role": "system", "content": system_prompt},
        {"role": "user", "content": user_content}
    ]

    try:
        response = await client.chat.completions.create(
            model=config.MODEL,
            messages=messages,
            tools=tools if tools else None,
            tool_choice="auto" if tools else None,
            temperature=config.TEMPERATURE_AGENT,
            timeout=config.TIMEOUT
        )

        message = response.choices[0].message

        if message.tool_calls:
            for tool_call in message.tool_calls:
                tool_name = tool_call.function.name
                tool_args = json.loads(tool_call.function.arguments)

                logger.info(f"Agent {agent_id} calling tool: {tool_name}")

                tool_result = await execute_tool(tool_name, tool_args)

                messages.append({
                    "role": "assistant",
                    "content": message.content,
                    "tool_calls": [
                        {
                            "id": tool_call.id,
                            "type": "function",
                            "function": {
                                "name": tool_name,
                                "arguments": tool_call.function.arguments
                            }
                        }
                    ]
                })

                messages.append({
                    "role": "tool",
                    "tool_call_id": tool_call.id,
                    "content": json.dumps(tool_result)
                })

            response = await client.chat.completions.create(
                model=config.MODEL,
                messages=messages,
                temperature=config.TEMPERATURE_AGENT,
                timeout=config.TIMEOUT
            )

            message = response.choices[0].message

        content = message.content.strip()

        try:
            result = json.loads(content)

            if "hypotheses" not in result:
                result = {
                    "agent_id": agent_id,
                    "role": role,
                    "hypotheses": [
                        {
                            "text": content,
                            "reasoning": "Direct response",
                            "confidence": 0.7,
                            "tools_used": []
                        }
                    ],
                    "self_eval": "Response generated without structured format"
                }

        except json.JSONDecodeError:
            result = {
                "agent_id": agent_id,
                "role": role,
                "hypotheses": [
                    {
                        "text": content,
                        "reasoning": "Agent provided unstructured response",
                        "confidence": 0.6,
                        "tools_used": []
                    }
                ],
                "self_eval": "Unable to parse as JSON"
            }

        logger.info(f"Agent {agent_id} ({role}) completed analysis")
        return result

    except Exception as e:
        logger.error(f"Agent {agent_id} ({role}) error: {e}")
        return {
            "agent_id": agent_id,
            "role": role,
            "hypotheses": [
                {
                    "text": f"Error during processing: {str(e)}",
                    "reasoning": "Agent encountered an error",
                    "confidence": 0.0,
                    "tools_used": []
                }
            ],
            "self_eval": f"Failed to complete analysis due to error: {str(e)}"
        }
