import asyncio
import json
import logging
from typing import Dict, Any, List
from openai import AsyncOpenAI
import config
from tools import get_tool_definitions

logging.basicConfig(level=config.LOG_LEVEL)
logger = logging.getLogger(__name__)

async def debate_and_consensus(
    client: AsyncOpenAI,
    agents_outputs: List[Dict[str, Any]],
    query: str,
    tools: List[Dict[str, Any]],
    iteration: int = 0
) -> Dict[str, Any]:

    system_prompt = """You are an Orchestrator coordinating multiple AI agents. Your role is to:

1. ANALYZE all agent hypotheses and identify:
   - Points of agreement
   - Points of conflict
   - Confidence levels
   - Quality of reasoning

2. DEBATE conflicting viewpoints:
   - Compare evidence and reasoning
   - Identify which arguments are stronger
   - Note gaps or weaknesses in each position

3. BUILD CONSENSUS:
   - Weight hypotheses by confidence and reasoning quality
   - Synthesize the best elements from multiple agents
   - Resolve conflicts through logical analysis

4. CALCULATE RELIABILITY:
   - Average confidence weighted by reasoning quality
   - Factor in agreement level among agents
   - Consider tool usage and evidence provided

Respond with valid JSON in this format:
{
  "best_hypothesis": "The consensus solution/answer",
  "reasoning": "How consensus was reached",
  "alternatives": ["Alternative 1", "Alternative 2"],
  "reliability": 0.0-1.0,
  "conflicts_resolved": true/false,
  "iteration": <number>
}

If reliability < 0.7 and conflicts remain, set conflicts_resolved to false."""

    agents_json = json.dumps(agents_outputs, indent=2)

    user_message = f"""Original Query: {query}

Agent Outputs:
{agents_json}

Current Iteration: {iteration + 1} of {config.MAX_DEBATE_ITERATIONS}

Perform debate and build consensus. If major conflicts exist and reliability is low, note that another iteration may be needed."""

    try:
        response = await client.chat.completions.create(
            model=config.MODEL,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_message}
            ],
            tools=tools if tools else None,
            tool_choice="auto" if tools else None,
            temperature=config.TEMPERATURE_ORCHESTRATOR,
            timeout=config.TIMEOUT
        )

        content = response.choices[0].message.content.strip()

        try:
            consensus = json.loads(content)
        except json.JSONDecodeError:
            import re
            reliability_match = re.search(r'"reliability"\s*:\s*(0\.\d+|1\.0)', content)
            reliability = float(reliability_match.group(1)) if reliability_match else 0.7

            consensus = {
                "best_hypothesis": content[:500],
                "reasoning": "Consensus extracted from unstructured response",
                "alternatives": [],
                "reliability": reliability,
                "conflicts_resolved": True,
                "iteration": iteration
            }

        consensus["iteration"] = iteration

        reliability = consensus.get("reliability", 0.7)
        conflicts_resolved = consensus.get("conflicts_resolved", True)

        logger.info(f"Orchestrator iteration {iteration + 1}: reliability={reliability:.2f}, resolved={conflicts_resolved}")

        if iteration < config.MAX_DEBATE_ITERATIONS - 1 and reliability < config.CONSENSUS_RELIABILITY_THRESHOLD and not conflicts_resolved:
            logger.info(f"Low reliability ({reliability:.2f}), starting iteration {iteration + 2}")

            critiques = await generate_critiques(client, consensus, agents_outputs)

            return await debate_and_consensus(
                client,
                agents_outputs + [{"critique": critiques}],
                query,
                tools,
                iteration + 1
            )

        return consensus

    except Exception as e:
        logger.error(f"Orchestrator error: {e}")

        best_by_confidence = max(
            [h for agent in agents_outputs for h in agent.get("hypotheses", [])],
            key=lambda x: x.get("confidence", 0.0),
            default={"text": "Unable to reach consensus", "confidence": 0.0}
        )

        return {
            "best_hypothesis": best_by_confidence.get("text", "Error in consensus building"),
            "reasoning": f"Fallback to highest confidence hypothesis due to error: {str(e)}",
            "alternatives": [],
            "reliability": best_by_confidence.get("confidence", 0.5),
            "conflicts_resolved": False,
            "iteration": iteration
        }

async def generate_critiques(
    client: AsyncOpenAI,
    consensus: Dict[str, Any],
    agents_outputs: List[Dict[str, Any]]
) -> str:

    critique_prompt = f"""Current consensus has low reliability. Generate constructive critiques:

Consensus: {consensus.get('best_hypothesis', 'N/A')}
Reliability: {consensus.get('reliability', 0.0)}

Agent Outputs Summary:
{json.dumps([{
    'agent_id': a.get('agent_id'),
    'role': a.get('role'),
    'confidence': max([h.get('confidence', 0) for h in a.get('hypotheses', [])], default=0)
} for a in agents_outputs], indent=2)}

Provide:
1. What assumptions might be wrong?
2. What evidence is missing?
3. What alternative approaches should be considered?
4. What specific improvements are needed?

Be specific and actionable."""

    try:
        response = await client.chat.completions.create(
            model=config.MODEL,
            messages=[
                {"role": "system", "content": "You are a critical analyst providing constructive feedback."},
                {"role": "user", "content": critique_prompt}
            ],
            temperature=config.TEMPERATURE_ORCHESTRATOR,
            timeout=config.TIMEOUT
        )

        return response.choices[0].message.content.strip()

    except Exception as e:
        logger.error(f"Error generating critiques: {e}")
        return "Unable to generate critiques due to error."
