    consensus: Dict[str, Any],
    query: str,
    original_agents_count: int
) -> Dict[str, Any]:

    system_prompt = """You are a Synthesizer creating the final user-facing response. Your role is to:

1. Transform the technical consensus into a clear, helpful answer
2. Maintain accuracy while being accessible
3. Provide step-by-step explanations when appropriate
4. Include alternative perspectives if valuable
5. Be transparent about confidence levels
6. Cite tool sources when relevant
7. Keep the Grok style: helpful, witty, truth-seeking, unfiltered

Structure your response:
- Direct answer to the question
- Detailed explanation with reasoning
- Alternative viewpoints (if relevant)
- Reliability assessment
- Recommendation for human verification (if reliability < 70%)

Be comprehensive but concise. Prioritize clarity and usefulness."""

    consensus_json = json.dumps(consensus, indent=2)
    reliability = consensus.get("reliability", 0.5)

    user_message = f"""Original Query: {query}

Consensus from {original_agents_count} specialized agents:
{consensus_json}

Generate the final user-facing response. Make it helpful, accurate, and appropriately confident."""

    try:
        response = await client.chat.completions.create(
            model=config.MODEL,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_message}
            ],
            temperature=config.TEMPERATURE_SYNTHESIZER,
            timeout=config.TIMEOUT
        )

        final_content = response.choices[0].message.content.strip()

        reliability_percentage = reliability * 100

        metadata = {
            "reliability": f"{reliability_percentage:.1f}%",
            "agents_consulted": original_agents_count,
            "iterations": consensus.get("iteration", 0) + 1,
            "alternatives_available": len(consensus.get("alternatives", []))
        }

        if reliability < 0.7:
            final_content += f"\n\n⚠️ Confidence Level: {reliability_percentage:.1f}% - I recommend human verification of this response."

        logger.info(f"Synthesis complete: {reliability_percentage:.1f}% reliability")

        return {
            "response": final_content,
            "metadata": metadata,
            "consensus": consensus
        }

    except Exception as e:
        logger.error(f"Synthesizer error: {e}")

        fallback_response = consensus.get("best_hypothesis", "Unable to generate response due to error.")

        return {
            "response": f"{fallback_response}\n\nNote: Response synthesis encountered an error. This is a direct output from the consensus process.",
            "metadata": {
                "reliability": f"{reliability * 100:.1f}%",
                "agents_consulted": original_agents_count,
                "iterations": consensus.get("iteration", 0) + 1,
                "error": str(e)
            },
            "consensus": consensus
        }
