import asyncio
import json
import logging
from datetime import datetime
from typing import Dict, Any
from openai import AsyncOpenAI
import config
from input_processor import evaluate_complexity
from agent import run_agent
from orchestrator import debate_and_consensus
from synthesizer import synthesize_response
from tools import get_tool_definitions

logging.basicConfig(
    level=config.LOG_LEVEL,
    format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler(config.LOG_FILE),
        logging.StreamHandler()
    ]
)
logger = logging.getLogger(__name__)

class MultiAgentSystem:
    def __init__(self, api_key: str = None):
        self.api_key = api_key or config.API_KEY
        if not self.api_key:
            raise ValueError("XAI_API_KEY environment variable not set")

        self.client = AsyncOpenAI(
            api_key=self.api_key,
            base_url=config.BASE_URL,
            timeout=config.TIMEOUT
        )

        self.tool_definitions = get_tool_definitions()
        logger.info("MultiAgentSystem initialized")

    async def process_query(self, query: str, enable_tools: bool = True) -> Dict[str, Any]:
        start_time = datetime.now()

        logger.info(f"Processing query: {query[:100]}...")

        try:
            num_agents, roles = await evaluate_complexity(query, self.client)

            logger.info(f"Complexity evaluation: {num_agents} agents with roles {set(roles)}")

            if num_agents == 1:
                logger.info("Single-agent mode: direct Grok call")
                response = await self.single_agent_mode(query, enable_tools)
            else:
                logger.info(f"Heavy mode: {num_agents} agents")
                response = await self.heavy_mode(query, num_agents, roles, enable_tools)

            end_time = datetime.now()
            duration = (end_time - start_time).total_seconds()

            response["metadata"]["processing_time_seconds"] = duration
            response["metadata"]["timestamp"] = end_time.isoformat()

            logger.info(f"Query processed in {duration:.2f} seconds")

            return response

        except Exception as e:
            logger.error(f"Error processing query: {e}", exc_info=True)
            return {
                "response": f"An error occurred while processing your query: {str(e)}",
                "metadata": {
                    "error": str(e),
                    "reliability": "0.0%"
                },
                "consensus": {}
            }

    async def single_agent_mode(self, query: str, enable_tools: bool) -> Dict[str, Any]:
        try:
            messages = [
                {
                    "role": "system",
                    "content": "You are Grok, a highly intelligent, helpful AI assistant. Provide accurate, clear, and insightful responses. Think step-by-step and be truth-seeking."
                },
                {
                    "role": "user",
                    "content": query
                }
            ]

            response = await self.client.chat.completions.create(
                model=config.MODEL,
                messages=messages,
                tools=self.tool_definitions if enable_tools else None,
                tool_choice="auto" if enable_tools else None,
                temperature=0.7,
                timeout=config.TIMEOUT
            )

            content = response.choices[0].message.content

            return {
                "response": content,
                "metadata": {
                    "mode": "single_agent",
                    "reliability": "85.0%",
                    "agents_consulted": 1,
                    "iterations": 1
                },
                "consensus": {
                    "best_hypothesis": content,
                    "reliability": 0.85
                }
            }

        except Exception as e:
            logger.error(f"Single agent mode error: {e}")
            raise

    async def heavy_mode(
        self,
        query: str,
        num_agents: int,
        roles: List[str],
        enable_tools: bool
    ) -> Dict[str, Any]:

        logger.info(f"Spawning {num_agents} agents in parallel")

        tools = self.tool_definitions if enable_tools else []

        agent_tasks = [
            run_agent(
                client=self.client,
                agent_id=i,
                role=roles[i],
                query=query,
                tools=tools
            )
            for i in range(num_agents)
        ]

        agents_outputs = await asyncio.gather(*agent_tasks, return_exceptions=True)

        valid_outputs = []
        for i, output in enumerate(agents_outputs):
            if isinstance(output, Exception):
                logger.error(f"Agent {i} failed: {output}")
                valid_outputs.append({
                    "agent_id": i,
                    "role": roles[i],
                    "hypotheses": [{
                        "text": "Agent failed to process",
                        "reasoning": str(output),
                        "confidence": 0.0,
                        "tools_used": []
                    }],
                    "self_eval": f"Error: {str(output)}"
                })
            else:
                valid_outputs.append(output)

        logger.info(f"Agents completed: {len(valid_outputs)} outputs collected")

        consensus = await debate_and_consensus(
            client=self.client,
            agents_outputs=valid_outputs,
            query=query,
            tools=tools
        )

        logger.info(f"Consensus reached: reliability={consensus.get('reliability', 0):.2f}")

        final_response = await synthesize_response(
            client=self.client,
            consensus=consensus,
            query=query,
            original_agents_count=num_agents
        )

        return final_response

    async def stream_process_query(self, query: str, enable_tools: bool = True):
        yield f"Starting multi-agent processing for query: {query[:100]}...\n\n"

        try:
            num_agents, roles = await evaluate_complexity(query, self.client)

            yield f"Complexity evaluation complete: {num_agents} agents\n"
            yield f"Roles assigned: {', '.join(set(roles))}\n\n"

            if num_agents == 1:
                yield "Using single-agent mode...\n\n"
                result = await self.single_agent_mode(query, enable_tools)
                yield f"Response:\n{result['response']}\n"
            else:
                yield f"Spawning {num_agents} agents in heavy mode...\n\n"

                tools = self.tool_definitions if enable_tools else []

                agent_tasks = [
                    run_agent(self.client, i, roles[i], query, tools)
                    for i in range(num_agents)
                ]

                agents_outputs = await asyncio.gather(*agent_tasks, return_exceptions=True)

                valid_outputs = [
                    output if not isinstance(output, Exception) else {
                        "agent_id": i,
                        "role": roles[i],
                        "hypotheses": [{"text": "Failed", "confidence": 0.0, "reasoning": str(output), "tools_used": []}],
                        "self_eval": f"Error: {str(output)}"
                    }
                    for i, output in enumerate(agents_outputs)
                ]

                yield f"Agents completed. Running debate and consensus...\n\n"

                consensus = await debate_and_consensus(self.client, valid_outputs, query, tools)

                yield f"Consensus reached (reliability: {consensus.get('reliability', 0) * 100:.1f}%)\n\n"

                final_response = await synthesize_response(self.client, consensus, query, num_agents)

                yield f"Final Response:\n{final_response['response']}\n"

        except Exception as e:
            yield f"\nError: {str(e)}\n"

